# This function unpacks a tensordesc object into its components:
# - data pointer
# - shape dimensions
# - stride values
def make_tensordesc_arg(arg):
    assert isinstance(arg, TensorDescriptor)
    data_ptr = arg.base.data_ptr()
    shape = arg.shape
    strides = arg.strides
    # Currently only contiguous tensors are supported
    assert strides[-1] == 1
    # The 0 is a placeholder that replaces the tensordesc type when passing to kernel.
    # nvidia oss backend passes tensordesc directly, but tileir needs to decompose it.
    result = [0, data_ptr, *shape, *strides]
    return result


def _expand_tensordesc_tuple(arg):
    result = []
    for value in arg:
        if isinstance(value, TensorDescriptor):
            result.extend(make_tensordesc_arg(value))
        elif isinstance(value, tuple):
            result.append(_expand_tensordesc_tuple(value))
        else:
            result.append(value)
    return tuple(result)


def wrap_handle_tensordesc(launcher):
    def inner(*args):
        # 9 is the metadata arguments in `args` defined in `make_launcher`
        meta_args = args[:9]
        raw_kernel_args = args[9:]
        final_args = []
        for i, arg in enumerate(raw_kernel_args):
            if isinstance(arg, TensorDescriptor):
                final_args.extend(make_tensordesc_arg(arg))
            elif isinstance(arg, tuple):
                final_args.append(_expand_tensordesc_tuple(arg))
            else:
                final_args.append(arg)
        return launcher(*meta_args, *final_args)

    return inner


class TileIRLauncher(object):
    def __init__(self, src, metadata):
        ids = {
            "ids_of_const_exprs": src.fn.constexprs if hasattr(src, "fn") else tuple()
        }

        constants = src.constants if hasattr(src, "constants") else dict()
        arg_idx = lambda x: (src.fn.arg_names.index(x),) if isinstance(x, str) else x
        constants = {arg_idx(idx): value for idx, value in constants.items()}
        signature = {idx: value for idx, value in src.signature.items()}
        def is_tensordesc(value):
            return isinstance(value, str) and value.startswith("tensordesc")

        def contains_tensordesc(value):
            if isinstance(value, tuple):
                return any(contains_tensordesc(element) for element in value)
            return is_tensordesc(value)

        def expand_tensordesc(value):
            shape_str = value.split("[", 1)[1].split("]", 1)[0]
            shape = [int(s) for s in shape_str.split(",")]
            dtype = value.split("<", 1)[1].split("[", 1)[0]
            return ["i32", f"*{dtype}", *(["i32"] * len(shape)), *(["i64"] * len(shape))]

        def expand_tuple(value):
            result = []
            for element in value:
                if is_tensordesc(element):
                    result.extend(expand_tensordesc(element))
                elif isinstance(element, tuple):
                    result.append(expand_tuple(element))
                else:
                    result.append(element)
            return tuple(result)

        has_tensordesc = any(contains_tensordesc(value) for value in signature.values())
        self.ori_signature_len = len(signature)
        if has_tensordesc:
            # Convert tensor descriptors to [placeholder, ptr, shape and stride].
            # Nested descriptors are expanded in place so the generated launcher
            # retains the original tuple structure.
            post_signature = {}
            for key, value in src.signature.items():
                key = arg_idx(key)
                if is_tensordesc(value):
                    for idx, expanded_type in enumerate(expand_tensordesc(value)):
                        post_signature[f"{key}_tensordesc_{idx}"] = expanded_type
                elif isinstance(value, tuple):
                    post_signature[key] = expand_tuple(value)
                else:
                    post_signature[key] = value
            self.signature = post_signature
        else:
            self.signature = signature
        self.constants = constants
        src = make_launcher(self.constants, self.signature)
        mod = compile_module_from_src(
            src, "__triton_launcher", library_dirs(), include_dirs, libraries
        )
        if has_tensordesc:
            self.launch = wrap_handle_tensordesc(mod.launch)
        else:
            self.launch = mod.launch
        self.launch_pdl = metadata.launch_pdl

    def __call__(self, *args, **kwargs):
        # TODO: below if branch is for torch 2.8.0a0+5228986c39.nvinternal commit
        # where constexpr arguments are not passed to the launch function by inductor
        # remove this after torch
        # 9 is the number of metadata arguments in `src` defined in `make_launcher`
        num_launch_args = 9
        num_params = len(args) - num_launch_args
        if num_params < self.ori_signature_len:
            extra_args = [
                self.constants[(i,)] for i in range(num_params, self.ori_signature_len)
            ]
            model_args = args + tuple(extra_args)
        else:
            model_args = args
        model_args = model_args[:5] + (self.launch_pdl,) + model_args[5:]

        self.launch(*model_args, **kwargs)


class TileIRDriver(GPUDriver):
    def __init__(self):
        self.utils = TileIRUtils()  # TODO: make static
        self.launcher_cls = TileIRLauncher
        super().__init__()

    def get_current_target(self):
        device = self.get_current_device()
        capability = self.get_device_capability(device)
        capability = capability[0] * 10 + capability[1]
        warp_size = 32
        return GPUTarget("tileir", capability, warp_size)

    def get_active_torch_device(self):
        import torch

        return torch.device("cuda", self.get_current_device())

    def get_device_interface(self):
        import torch

        return torch.cuda

    @staticmethod
    def is_active():
        try:
            import torch

            return (
                torch.cuda.is_available()
                and os.environ.get("ENABLE_TILE", "0") == "1"
                and (torch.version.hip is None)
            )
        except ImportError:
            return False

    def map_python_to_cpp_type(self, ty: str) -> str:
        return ty_to_cpp(ty)

    def get_benchmarker(self):
        from triton.testing import do_bench

        return do_bench

    def get_empty_cache_for_benchmark(self):
        import torch

        # We maintain a buffer of 256 MB that we clear
        # before each kernel call to make sure that the L2 cache
        # doesn't contain any input data before the run
        cache_size = 256 * 1024 * 1024
        return torch.empty(int(cache_size // 4), dtype=torch.int, device="cuda")

    def clear_cache(self, cache):
        cache.zero_()


